UPDATE public.songs s SET rationale=n.rationale FROM (VALUES
('yacht_rock','peg','Pristine ensemble precision with a watchful perspective; a sophisticated foil for soft-focus solitude.'),
('yacht_rock','sailing','Weightless private escape, all atmosphere and patient drift rather than command or rhythmic insistence.'),
('yacht_rock','rosanna','A muscular, immaculate studio groove with a big communal chorus, showing how refined playing can still push.'),
('yacht_rock','what_a_fool','A buoyant arrangement conceals romantic self-deception: seemingly frictionless sound, emotionally complicated story.'),
('yacht_rock','i_keep_forgettin','The bass-driven groove commands the body while the lyric stays stuck in emotional denial.'),
('yacht_rock','lowdown','Slick, judgmental funk that rewards an assertive, observational stance over tender vulnerability.'),
('yacht_rock','baby_come_back','A polished but exposed plea that sets confidence aside to live inside unresolved longing.'),
('yacht_rock','reminiscing','Harmonies and nostalgia turn a private romantic memory into an expansive, effortless glide.'),
('yacht_rock','biggest_part','Ornate harmonies and heartfelt reassurance reward warmth and immaculate finish over lyrical distance.'),
('yacht_rock','georgy_porgy','A layered, laid-back jazz-funk groove asks for patient attention rather than a decisive shout.'),
('yacht_rock','this_is_it','An urgent life-advice anthem disguised as soft rock, with the vocalist pushing rather than floating.'),
('yacht_rock','deacon_blues','An elaborate, inwardly weary narrator rewards close observation and slow accumulation over easy release.'),
('yacht_rock','you_make_my_dreams','Sunny, immediate pop insistence tests the appetite for public joy over patient, solitary drift.'),
('yacht_rock','i_cant_go_for_that','An economical synthetic groove and cool boundary-setting contrast with open-ended tenderness.'),
('yacht_rock','summer_breeze','Unhurried acoustic atmosphere and a sense of place invite escape rather than spectacle or command.'),
('disco','good_times','The band makes repetition feel effortlessly communal, turning the rhythm section into a party invitation.'),
('disco','i_feel_love','Giorgio Moroder''s synthetic pulse asks for surrender to an evolving machine, not a singalong band.'),
('disco','stayin_alive','Tough swagger and precision groove make confidence sound cool rather than explosive.'),
('disco','i_will_survive','Private betrayal becomes collective self-possession; a defining case of vulnerability rewritten as command.'),
('disco','september','A highly arranged communal celebration with no demand for suspense or menace.'),
('disco','we_are_family','Group identity is the refrain; the most literal test of pleasure becoming belonging.'),
('disco','disco_inferno','Relentless, large-scale disco heat turns a celebration into near-dangerous spectacle.'),
('disco','get_down_tonight','A simple rhythmic demand for the present moment, built for instant group movement.'),
('disco','im_coming_out','Nile Rodgers'' groove underwrites a sweeping public declaration of becoming oneself.'),
('disco','shame','Emotional doubt runs under buoyant dance-floor command, complicating uncomplicated disco joy.'),
('disco','you_make_me_feel','Vocal ecstasy and electronic acceleration make the floor a place of ecstatic public self-assertion.'),
('disco','turn_beat_around','A rhythmic command with percussion up front, where action matters more than patient atmosphere.'),
('disco','rock_your_baby','Featherweight tenderness and a relaxed groove are a softer point of entry to disco pleasure.'),
('disco','supernature','A cinematic, ominous synthetic epic takes disco beyond the social floor toward the uncanny.'),
('disco','dont_leave_me','A vulnerable, gospel-sized plea made massive by orchestration and dance-floor scale.'),
('disco','dont_stop_til','An impeccably layered dance record that keeps developing around a light, assured vocal.'),
('disco','dancing_queen','A cinematic shared memory packaged as an immediate, glamorous singalong.'),
('disco','love_hangover','A languid intimate opening becomes a full disco release, making transformation the actual attraction.'),
('punk','blitzkrieg','The chant and the rush are the point: an instantaneous communal jolt with no narrative detour.'),
('punk','london_calling','An outward-looking warning on a grander arrangement, asking for critical attention as well as motion.'),
('punk','anarchy','An openly confrontational proclamation that measures appetite for threat and public provocation.'),
('punk','holiday','Fierce satire places an abrasive political viewpoint above uncomplicated group release.'),
('punk','ever_fallen','A brisk melodic heartbreak song where raw speed conceals emotional doubt.'),
('punk','new_rose','An unpolished first-wave adrenaline surge with little interest in extended argument.'),
('punk','teenage_kicks','Young romance wins over menace; a direct, buoyant melodic foil for ideological punk.'),
('punk','los_angeles','An ugly, unsparing portrait of a place, driven by roots-inflected speed and observational friction.'),
('punk','rise_above','A clenched communal refusal, engineered for collective resistance more than private doubt.'),
('punk','straight_edge','A tiny manifesto of self-discipline delivered with radical speed and personal command.'),
('punk','banned_dc','Virtuosic hardcore volatility tests the attraction of dramatic pivots inside extreme speed.'),
('punk','bondage','A confrontational, sax-laced blast of feminism that wants to change the argument, not just the tempo.'),
('punk','basket_case','Radio-bright velocity carries anxious self-doubt, upending the expectation that speed means certainty.'),
('punk','typical_girls','Elastic rhythms and social critique make a long, exploratory argument rather than a straight-line attack.'),
('punk','twelve_xu','Bare rhythmic abrasion and formal economy privilege cut-to-the-bone energy over complexity.'),
('punk','alternative_ulster','An urgent, place-specific call for change turns guitar attack into collective political expression.'),
('punk','ruby_soho','Ska-inflected camaraderie makes streetwise punk singable and emotionally inviting.'),
('punk','self_esteem','Blunt guitars frame a confession of romantic capitulation, separating loudness from emotional control.'),
('reggae','three_little_birds','A soft, public reassurance whose optimistic refrain asks for release rather than confrontation.'),
('reggae','marcus_garvey','A commanding historical and political invocation that keeps pressure alive inside a hypnotic roots groove.'),
('reggae','harder_come','Personal resilience becomes a public declaration, with bright momentum and hard-earned defiance.'),
('reggae','pressure_drop','A brisk soul-inflected communal groove, driven more by infectious immediacy than slow immersion.'),
('reggae','israelites','A deceptively light hit carries economic strain, rewarding listeners who hear the story under the bounce.'),
('reggae','night_nurse','Velvet intimacy and aching need sit at the opposite end of the genre from public protest.'),
('reggae','money_pocket','A gently buoyant, personal romance uses reggae rhythm without the pressure of a manifesto.'),
('reggae','legalize_it','A direct political demand where defiance matters more than gentle background comfort.'),
('reggae','guess_who','Dense atmosphere and a watchful threat make this a patient, ominous counterweight to sunny reggae.'),
('reggae','king_tubby','Space, echo and subtraction become the narrative; a defining contrast to singer-led directness.'),
('reggae','java','Melodica-led instrumental meditation values space and slow development over lyrical command.'),
('reggae','fisherman','Haunting harmonies and spiritual imagery pull the listener inward through ritual repetition.'),
('reggae','bam_bam','Playful and assertive dancehall voice, immediate and crowd-minded rather than atmospheric.'),
('reggae','zungu','A chant-like deejay performance privileges swagger, rough immediacy and group response.'),
('reggae','you_dont_love_me','A polished but wounded vocal on a dancehall pulse, exposing hesitation behind the beat.'),
('reggae','handsworth','UK roots reggae politicizes a specific place and makes group resistance the main attraction.'),
('reggae','get_busy','A high-motion, instantly communal dancehall crossover with almost no patience for quiet reflection.'),
('reggae','welcome_jamrock','A huge, urgent social observation pushes reggae''s public stakes to the foreground.')
) n(lane,k,rationale) WHERE s.id=md5('musicdna:'||n.lane||':2026-11-10:song:'||n.k)::uuid AND s.rationale IS NULL;